insert into page_content (page, section, field, value, content_type, status) values ('mennesker', 'hero', 'mennesker-h1', 'Det rigtige match begynder med mennesket bag CV''et', 'text', 'published') on conflict (page, section, field) do update set value = excluded.value;
insert into page_content (page, section, field, value, content_type, status) values ('mennesker', 'hero', 'mennesker-intro-1', 'At ramme rigtigt fra første dag er afgørende. Matcher mennesket bag CV''et jeres team, kultur og organisation, øger I sandsynligheden for bedre trivsel, hurtigere integration og lavere personaleomsætning.', 'text', 'published') on conflict (page, section, field) do update set value = excluded.value;
insert into page_content (page, section, field, value, content_type, status) values ('mennesker', 'hero', 'mennesker-intro-2', 'Har I brug for hjælp til rekruttering, personprofiler eller en mere struktureret onboarding, hjælper vi jer med at skabe et forløb, hvor både virksomheden og den nye medarbejder får den bedst mulige start.', 'text', 'published') on conflict (page, section, field) do update set value = excluded.value;
insert into page_content (page, section, field, value, content_type, status) values ('mennesker', 'hero', 'mennesker-cta-question', 'Skal vi finde det rigtige match?', 'text', 'published') on conflict (page, section, field) do update set value = excluded.value;
insert into page_content (page, section, field, value, content_type, status) values ('mennesker', 'hero', 'mennesker-cta-button', 'Book en samtale', 'text', 'published') on conflict (page, section, field) do update set value = excluded.value;
insert into page_content (page, section, field, value, content_type, status) values ('mennesker', 'hero', 'mennesker-challenge', 'Stillinger står åbne for længe, nye medarbejdere matcher ikke rollen eller kulturen, og onboarding er tilfældig snarere end struktureret.', 'text', 'published') on conflict (page, section, field) do update set value = excluded.value;
insert into page_content (page, section, field, value, content_type, status) values ('mennesker', 'hero', 'mennesker-benefit-1', 'Hurtigere rekruttering', 'text', 'published') on conflict (page, section, field) do update set value = excluded.value;
