insert into page_content (page, section, field, value, content_type, status) values ('mennesker', 'hero', 'mennesker-benefit-3', 'Lavere personaleomsætning', 'text', 'published') on conflict (page, section, field) do update set value = excluded.value;
insert into page_content (page, section, field, value, content_type, status) values ('mennesker', 'hero', 'mennesker-benefit-4', 'Stærkere onboarding', 'text', 'published') on conflict (page, section, field) do update set value = excluded.value;
insert into page_content (page, section, field, value, content_type, status) values ('mennesker', 'hero', 'mennesker-svc1-title', 'Rekruttering', 'text', 'published') on conflict (page, section, field) do update set value = excluded.value;
insert into page_content (page, section, field, value, content_type, status) values ('mennesker', 'hero', 'mennesker-svc1-desc', 'Målrettet rekrutteringsproces fra behovsafklaring over kandidatvurdering til onboarding — så den nye medarbejder rammer rigtigt fra dag ét.', 'text', 'published') on conflict (page, section, field) do update set value = excluded.value;
insert into page_content (page, section, field, value, content_type, status) values ('mennesker', 'hero', 'mennesker-svc1-long', 'Vi bygger rekrutteringsprocessen op omkring den reelle kravprofil — ikke en generisk stillingsskabelon. Fra behovsafklaring med den ansættende leder, over struktureret kandidatvurdering, til en onboarding-plan der sikrer, at den nye medarbejder er produktiv fra dag ét.', 'text', 'published') on conflict (page, section, field) do update set value = excluded.value;
insert into page_content (page, section, field, value, content_type, status) values ('mennesker', 'hero', 'mennesker-svc1-challenges', 'Stillinger, der står åbne for længe. Kandidater, der ser rigtige ud på papiret men ikke passer til kulturen. Onboarding, der er tilfældig og afhænger af, hvem der lige har tid.', 'text', 'published') on conflict (page, section, field) do update set value = excluded.value;
insert into page_content (page, section, field, value, content_type, status) values ('mennesker', 'hero', 'mennesker-svc1-approach', 'Vi starter med en skarp kravprofil, bruger strukturerede samtaler frem for mavefornemmelse, og lader IPA nordic-profiler kvalificere — ikke afgøre — den endelige beslutning.', 'text', 'published') on conflict (page, section, field) do update set value = excluded.value;
insert into page_content (page, section, field, value, content_type, status) values ('mennesker', 'hero', 'mennesker-svc1-results', 'Kortere time-to-hire, færre fejlansættelser og en onboarding, der er ens, uanset hvem der ansætter.', 'text', 'published') on conflict (page, section, field) do update set value = excluded.value;
