insert into page_content (page, section, field, value, content_type, status) values ('mennesker', 'hero', 'mennesker-svc2-title', 'Personprofiler (IPA nordic)', 'text', 'published') on conflict (page, section, field) do update set value = excluded.value;
insert into page_content (page, section, field, value, content_type, status) values ('mennesker', 'hero', 'mennesker-svc2-desc', 'Præcis indsigt i adfærd, motivation og potentiale. Bruges til rekruttering, udvikling og sammensætning af stærkere teams.', 'text', 'published') on conflict (page, section, field) do update set value = excluded.value;
insert into page_content (page, section, field, value, content_type, status) values ('mennesker', 'hero', 'mennesker-svc2-long', 'IPA nordic-profiler bruges systematisk gennem hele medarbejderrejsen — fra rekruttering, over udvikling af eksisterende medarbejdere, til sammensætning af teams, der reelt komplementerer hinanden.', 'text', 'published') on conflict (page, section, field) do update set value = excluded.value;
insert into page_content (page, section, field, value, content_type, status) values ('mennesker', 'hero', 'mennesker-svc2-challenges', 'Beslutninger om ansættelse og forfremmelse baseret på mavefornemmelse. Teams, der er sammensat tilfældigt frem for bevidst. Udviklingssamtaler uden et fælles sprog for adfærd og motivation.', 'text', 'published') on conflict (page, section, field) do update set value = excluded.value;
insert into page_content (page, section, field, value, content_type, status) values ('mennesker', 'hero', 'mennesker-svc2-approach', 'Profilen bruges som samtaleredskab, ikke facitliste — den kvalificerer dialogen mellem leder og medarbejder, og gør det muligt at sætte ord på styrker og udviklingspotentiale.', 'text', 'published') on conflict (page, section, field) do update set value = excluded.value;
insert into page_content (page, section, field, value, content_type, status) values ('mennesker', 'hero', 'mennesker-svc2-results', 'Mere præcise ansættelser, stærkere teamsammensætning og udviklingssamtaler med substans.', 'text', 'published') on conflict (page, section, field) do update set value = excluded.value;
