insert into page_content (page, section, field, value, content_type, status) values ('mennesker', 'hero', 'mennesker-case-title', 'Produktionsvirksomhed, ca. 60 medarbejdere', 'text', 'published') on conflict (page, section, field) do update set value = excluded.value;
insert into page_content (page, section, field, value, content_type, status) values ('mennesker', 'hero', 'mennesker-case-situation', 'Høj udskiftning i produktionen og lang tid til besættelse af ledige stillinger.', 'text', 'published') on conflict (page, section, field) do update set value = excluded.value;
insert into page_content (page, section, field, value, content_type, status) values ('mennesker', 'hero', 'mennesker-case-retning', 'Mennesker — rekrutteringsproces og personprofiler.', 'text', 'published') on conflict (page, section, field) do update set value = excluded.value;
