insert into page_content (page, section, field, value, content_type, status) values ('mennesker', 'hero', 'mennesker-case-resultat', 'Kortere time-to-hire og markant færre opsigelser i prøvetiden.', 'text', 'published') on conflict (page, section, field) do update set value = excluded.value;
