insert into page_content (page, section, field, value, content_type, status) values ('mennesker', 'hero', 'mennesker-insight1-q', 'Derfor koster en fejlansættelse mere, end du tror', 'text', 'published') on conflict (page, section, field) do update set value = excluded.value;
insert into page_content (page, section, field, value, content_type, status) values ('mennesker', 'hero', 'mennesker-insight1-a', 'De direkte omkostninger er sjældent problemet — det er tidsforbruget, den tabte produktivitet og den kultur-smitte, en forkert ansættelse efterlader i teamet.', 'text', 'published') on conflict (page, section, field) do update set value = excluded.value;
insert into page_content (page, section, field, value, content_type, status) values ('mennesker', 'hero', 'mennesker-insight2-q', 'Sådan bruges personprofiler rigtigt', 'text', 'published') on conflict (page, section, field) do update set value = excluded.value;
