insert into page_content (page, section, field, value, content_type, status) values ('ledelse', 'hero', 'ledelse-svc1-title', 'Ledelse &amp; Coaching', 'text', 'published') on conflict (page, section, field) do update set value = excluded.value;
insert into page_content (page, section, field, value, content_type, status) values ('ledelse', 'hero', 'ledelse-svc1-desc', 'Ledelsessparring og coaching, der styrker beslutningskraft, retning og gennemslagskraft hos den enkelte leder.', 'text', 'published') on conflict (page, section, field) do update set value = excluded.value;
insert into page_content (page, section, field, value, content_type, status) values ('ledelse', 'hero', 'ledelse-svc1-long', 'Individuel ledelsessparring, der tager udgangspunkt i lederens konkrete udfordringer — ikke en generisk lederuddannelse. Faste samtaler over en periode, med fokus på beslutningskraft, retning og gennemslagskraft.', 'text', 'published') on conflict (page, section, field) do update set value = excluded.value;
insert into page_content (page, section, field, value, content_type, status) values ('ledelse', 'hero', 'ledelse-svc1-challenges', 'Beslutninger, der trækker ud. Nye ledere, der mangler et rum til at tænke højt. Prioritering, der skifter alt efter hvem der råber højest.', 'text', 'published') on conflict (page, section, field) do update set value = excluded.value;
insert into page_content (page, section, field, value, content_type, status) values ('ledelse', 'hero', 'ledelse-svc1-approach', 'Fast, tilbagevendende sparring — ofte månedligt — kombineret med konkret træning i de samtaler og beslutninger, lederen reelt står overfor lige nu.', 'text', 'published') on conflict (page, section, field) do update set value = excluded.value;
insert into page_content (page, section, field, value, content_type, status) values ('ledelse', 'hero', 'ledelse-svc1-results', 'Hurtigere og mere konsistente beslutninger, en tydeligere ledelsesstil og en leder, organisationen kan følge.', 'text', 'published') on conflict (page, section, field) do update set value = excluded.value;
