insert into page_content (page, section, field, value, content_type, status) values ('ledelse', 'hero', 'ledelse-svc2-desc', 'Erfaren ledelseskraft i en periode med forandring, vakance eller vækst — indtil den faste organisation er på plads.', 'text', 'published') on conflict (page, section, field) do update set value = excluded.value;
insert into page_content (page, section, field, value, content_type, status) values ('ledelse', 'hero', 'ledelse-svc2-long', 'Erfaren ledelseskraft, der træder ind i en periode med forandring, vakance eller vækst — og sikrer, at driften og udviklingen fortsætter, mens den faste organisation falder på plads.', 'text', 'published') on conflict (page, section, field) do update set value = excluded.value;
