insert into page_content (page, section, field, value, content_type, status) values ('mfg-compass', 'hero', 'mfgcompass-hero-title', 'Udvikling virker først, når helheden hænger sammen', 'text', 'published') on conflict (page, section, field) do update set value = excluded.value;
insert into page_content (page, section, field, value, content_type, status) values ('mfg-compass', 'hero', 'mfgcompass-hero-intro', 'The MFG Compass™ samler mennesker, ledelse, kultur og forretning i én fælles retning. Metoden skaber et klart billede af, hvor organisationen står, hvor potentialet ligger, og hvad der skal prioriteres for at omsætte ambitioner til målbare resultater.', 'text', 'published') on conflict (page, section, field) do update set value = excluded.value;
insert into page_content (page, section, field, value, content_type, status) values ('mfg-compass', 'hero', 'mfgcompass-people-text', 'Vi ser mennesket, før vi ser rollen. Udvikling begynder med forståelse for kompetencer, motivation, ansvar og potentiale.', 'text', 'published') on conflict (page, section, field) do update set value = excluded.value;
insert into page_content (page, section, field, value, content_type, status) values ('mfg-compass', 'hero', 'mfgcompass-leadership-text', 'Vi skaber retning gennem ledelse. Tydelige valg, klare forventninger og konsekvent opfølgning gør strategien anvendelig i hverdagen.', 'text', 'published') on conflict (page, section, field) do update set value = excluded.value;
insert into page_content (page, section, field, value, content_type, status) values ('mfg-compass', 'hero', 'mfgcompass-culture-text', 'Vi bygger en kultur, hvor mennesker lykkes. Adfærd, samarbejde og fælles standarder skal understøtte den retning, virksomheden ønsker.', 'text', 'published') on conflict (page, section, field) do update set value = excluded.value;
insert into page_content (page, section, field, value, content_type, status) values ('mfg-compass', 'hero', 'mfgcompass-business-text', 'Vi omsætter potentiale til resultater. Udviklingen skal kunne mærkes i drift, kunder, økonomi og organisationens evne til at levere.', 'text', 'published') on conflict (page, section, field) do update set value = excluded.value;
