insert into page_content (page, section, field, value, content_type, status) values ('mfg-compass', 'hero', 'mfgcompass-step1-text', 'Vi afdækker virksomhedens situation, mål og vigtigste udfordringer.', 'text', 'published') on conflict (page, section, field) do update set value = excluded.value;
