insert into page_content (page, section, field, value, content_type, status) values ('mfg-compass', 'hero', 'mfgcompass-step4-title', 'Forankring', 'text', 'published') on conflict (page, section, field) do update set value = excluded.value;
insert into page_content (page, section, field, value, content_type, status) values ('mfg-compass', 'hero', 'mfgcompass-step4-text', 'Løsningerne omsættes til handling, ansvar og opfølgning i organisationen.', 'text', 'published') on conflict (page, section, field) do update set value = excluded.value;
insert into page_content (page, section, field, value, content_type, status) values ('mfg-compass', 'hero', 'mfgcompass-why-text', 'En stærk strategi skaber ikke resultater alene. Den skal bæres af ledelsen, forstås af menneskerne og understøttes af kulturen. Omvendt skaber trivsel og engagement heller ikke varige resultater, hvis retning, ansvar og kommercielt fokus mangler. The MFG Compass™ gør sammenhængene synlige og skaber et fælles grundlag for beslutninger og udvikling.', 'text', 'published') on conflict (page, section, field) do update set value = excluded.value;
insert into page_content (page, section, field, value, content_type, status) values ('mfg-compass', 'hero', 'mfgcompass-cta-title', 'Hvor peger jeres kompas hen?', 'text', 'published') on conflict (page, section, field) do update set value = excluded.value;
insert into page_content (page, section, field, value, content_type, status) values ('mfg-compass', 'hero', 'mfgcompass-cta-text', 'En strategisk samtale kan være første skridt til at skabe klarhed over retning, potentiale og de vigtigste næste handlinger.', 'text', 'published') on conflict (page, section, field) do update set value = excluded.value;
